var next: usize = 0;

fn onPanic(msg: []const u8, _: ?usize) noreturn {
    const r = rows[next - 1];
    const kind = if (std.mem.eql(u8, msg, "shift amount is greater than the type size")) "shiftRhsTooBig" else "other";
    std.debug.print("P {s} {d} {d} {d} panic {s}\n", .{ r.tag, r.sel, r.v, r.k, kind });
    runRows();
}

fn runRows() noreturn {
    while (next < rows.len) {
        const r = rows[next];
        next += 1;
        const x = r.f(r.sel, @truncate(r.v >> 128), @truncate(r.v), r.k);
        std.debug.print("P {s} {d} {d} {d} ok {d}\n", .{ r.tag, r.sel, r.v, r.k, x });
    }
    std.process.exit(0);
}

pub fn main() void {
    runRows();
}
